const fn new(data: T) -> Self {
        Self {
            marker: PhantomData,
            storage: UnsafeCell::new(data),
            #[cfg(feature = "smp")]
            flag: AtomicBool::new(false),
        }
    }

const fn new(data: T) -> Self {
        Self::new_with_stats(data, &klockstat::NOOP_CLASS)
    }

fn parent(&self) -> Option<Self> {
        self.0.location.read().parent.clone()
    }

fn parent(&self) -> Option<Dentry> {
        self.location.parent.clone()
    }

fn new_dir<T>(node: Arc<T>, init: VfsInodeInit) -> Arc<Self>
    where
        T: Any + Send + Sync + InodeOperations,
    {
        let private_data: Arc<dyn Any + Send + Sync> = node.clone();
        let inode_operations: Arc<dyn InodeOperations> = node;
        Self::new_dir_with_inode_operations(
            private_data,
            inode_operations,
            NodeFlags::empty(),
            init,
        )
    }

fn new_dir_with_flags<T>(node: Arc<T>, flags: NodeFlags, init: VfsInodeInit) -> Arc<Self>
    where
        T: Any + Send + Sync + InodeOperations,
    {
        let private_data: Arc<dyn Any + Send + Sync> = node.clone();
        let inode_operations: Arc<dyn InodeOperations> = node;
        Self::new_dir_with_inode_operations(private_data, inode_operations, flags, init)
    }

