const fn new(data: T) -> Self {
        Self {
            marker: PhantomData,
            state: AtomicUsize::new(0),
            storage: UnsafeCell::new(data),
        }
    }

const fn with_permission(self, permission: NodePermission) -> Self {
        Self((self.0 & NODE_TYPE_MASK) | (permission.bits() & PERMISSION_MASK))
    }

const fn with_node_type(self, node_type: NodeType) -> Self {
        Self(((node_type as u16) << NODE_TYPE_SHIFT) | (self.0 & PERMISSION_MASK))
    }

fn new_regular(fs: Arc<SimpleFs>, ops: impl SimpleFileOps) -> Arc<Self> {
        Self::new(fs, NodeType::RegularFile, ops)
    }

fn new(fs: Arc<SimpleFs>, ty: NodeType, ops: impl SimpleFileOps) -> Arc<Self> {
        Self::new_regular_with_type(fs, ty, NodePermission::default(), ops)
    }

