fn set_nonblocking(&self, flag: bool) {
        if flag {
            self.flags
                .fetch_or(OpenFlags::NONBLOCK.bits(), Ordering::AcqRel);
        } else {
            self.flags
                .fetch_and(!OpenFlags::NONBLOCK.bits(), Ordering::AcqRel);
        }
    }

fn set_nonblocking(&mut self, flag: bool) {
        if flag {
            self.flags.insert(OpenFlags::NONBLOCK);
        } else {
            self.flags.remove(OpenFlags::NONBLOCK);
        }
    }

const fn new(pos: u64, len: usize) -> Self {
        Self { pos, len }
    }

const fn new(pos: u64, len: usize, copied: usize) -> Self {
        Self { pos, len, copied }
    }

const fn is_empty(self) -> bool {
        self.len == 0
    }

const fn is_empty(self) -> bool {
        self.len == 0
    }

fn d_is_dir(dentry: &Dentry) -> bool {
    dentry.is_dir_entry()
}

fn is_dir_entry(&self) -> bool {
        self.can_lookup() || self.is_autodir()
    }

fn is_really_positive(&self) -> bool {
        !self.is_really_negative()
    }

fn d_really_is_positive(dentry: &Dentry) -> bool {
    dentry.is_really_positive()
}

fn writeback_mapping_range(
        &self,
        start: u64,
        len: usize,
        data_only: bool,
    ) -> VfsResult<()> {
        self.mapping().writepages_range(start, len, data_only)
    }

fn writepages_range(&self, start: u64, len: usize, data_only: bool) -> VfsResult<()> {
        let mut control = WritebackControl::range(start, len, data_only)?;
        self.writepages_control(&mut control)
    }

unsafe fn get_unchecked(&self) -> &T {
        debug_assert_eq!(
            self.state.load(Ordering::SeqCst),
            Status::Ready,
            "Attempted to access an uninitialized OnceCell. If this was run without debug checks, \
             this would be undefined behaviour. This is a serious bug and you must fix it.",
        );
        // SAFETY: The caller promises the cell is initialized; the debug
        // assertion checks that contract in debug builds.
        unsafe { self.get_value_unchecked() }
    }

unsafe fn get_mut_unchecked(&mut self) -> &mut T {
        debug_assert_eq!(
            self.state.load(Ordering::SeqCst),
            Status::Ready,
            "Attempted to access an uninitialized OnceCell. If this was run without debug checks, \
             this would be undefined behavior. This is a serious bug and you must fix it.",
        );
        // SAFETY: The caller promises the cell is initialized; the debug
        // assertion checks that contract in debug builds.
        unsafe { self.get_value_mut_unchecked() }
    }

fn downcast<T: Any + Send + Sync>(&self) -> VfsResult<Arc<T>> {
        self.private_data
            .clone()
            .downcast()
            .map_err(|_| VfsError::InvalidInput)
    }

fn downcast<T: Any + Send + Sync>(&self) -> VfsResult<Arc<T>> {
        self.vfs_inode().downcast()
    }
